const { build } = require('esbuild');
const { readFile, writeFile } = require('node:fs/promises');
const { dirname, join, resolve } = require('node:path');

const root = resolve(__dirname, '..');
const processorPath = join(dirname(require.resolve('spessasynth_lib')), 'spessasynth_processor.min.js');

function replaceOnce(source, before, after) {
    const index = source.indexOf(before);
    if (index < 0 || source.indexOf(before, index + before.length) !== -1) {
        throw new Error(`stb-vorbis changed; review the browser compatibility patch: ${before}`);
    }
    return source.slice(0, index) + after + source.slice(index + before.length);
}

async function buildBrowser() {
    await build({
        absWorkingDir: root,
        entryPoints: ['src/main.js'],
        outfile: 'main.min.js',
        bundle: true,
        format: 'esm',
        minify: true,
        supported: { 'template-literal': false },
        banner: { js: '// Generated by npm run build from src/main.js.' },
        legalComments: 'eof',
        plugins: [{
            name: 'async-vorbis-on-main-thread',
            setup(builder) {
                builder.onLoad({ filter: /[/\\]stb-vorbis[/\\]dist[/\\]index\.js$/ }, async ({ path }) => {
                    const source = await readFile(path, 'utf8');
                    // Chromium can reject synchronous WASM instantiation above 4 KB on the UI thread.
                    // Decode stays synchronous once the initial instance (or a replacement) is ready.
                    let contents = replaceOnce(source, 'A.module=await WebAssembly.compile(C),A.exports=A.createInstance()', 'A.module=await WebAssembly.compile(C),A.exports=await A.createInstance()');
                    contents = replaceOnce(contents, 'static createInstance()', 'static async createInstance()');
                    contents = replaceOnce(contents, 'new WebAssembly.Instance(I,a).exports', '(await WebAssembly.instantiate(I,a)).exports');
                    contents = replaceOnce(contents,
                        'static resetInstance(){try{A.exports=A.createInstance()}catch{A.exports=void 0}}',
                        'static resetInstance(){A.exports=void 0;A.createInstance().then(exports=>{A.exports=exports},()=>{})}');
                    return { contents, resolveDir: dirname(path) };
                });
            },
        }],
    });

    // The worklet already runs off the UI thread. Keep its upstream code and omit
    // the source map reference, since that map isn't published next to the asset.
    const processor = await readFile(processorPath, 'utf8');
    await writeFile(join(root, 'spessasynth_processor.min.js'), processor.replace(/^\/\/# sourceMappingURL=.*\r?\n?$/m, ''));
}

buildBrowser().catch(error => { console.error(error); process.exitCode = 1; });
